PRAGMA foreign_keys=ON;
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),auto_enabled INTEGER NOT NULL DEFAULT 1,interval_days INTEGER NOT NULL DEFAULT 1 CHECK(interval_days BETWEEN 1 AND 30),freshness_hours INTEGER NOT NULL DEFAULT 48 CHECK(freshness_hours BETWEEN 24 AND 1440),last_auto_at TEXT);
INSERT INTO settings(id) VALUES(1);
CREATE TABLE shops(id TEXT PRIMARY KEY,platform TEXT NOT NULL,token TEXT,name TEXT NOT NULL,url TEXT NOT NULL,data TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'ok',checked_at TEXT,error TEXT);
CREATE TRIGGER shop_cap BEFORE INSERT ON shops WHEN (SELECT COUNT(*) FROM shops)>=30 BEGIN SELECT RAISE(ABORT,'最多接入30家店铺'); END;
CREATE TABLE products(id TEXT PRIMARY KEY,category TEXT NOT NULL,data TEXT NOT NULL);
CREATE TABLE mappings(shop_id TEXT NOT NULL,source_id TEXT NOT NULL,sku TEXT NOT NULL REFERENCES products(id),fingerprint TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(shop_id,source_id));
CREATE TABLE goods(id TEXT PRIMARY KEY,shop_id TEXT NOT NULL REFERENCES shops(id),source_id TEXT NOT NULL,title TEXT NOT NULL,fingerprint TEXT NOT NULL DEFAULT '',raw TEXT,data_at TEXT NOT NULL,run_id TEXT,page INTEGER NOT NULL DEFAULT 1,reason TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX goods_shop ON goods(shop_id,review_status);
CREATE TABLE quotes(id TEXT PRIMARY KEY,shop_id TEXT NOT NULL REFERENCES shops(id),sku TEXT NOT NULL REFERENCES products(id),data TEXT NOT NULL);
CREATE INDEX quotes_sku ON quotes(sku);
CREATE INDEX quotes_shop ON quotes(shop_id);
CREATE TABLE observations(quote_id TEXT NOT NULL,sku TEXT NOT NULL,checked_at TEXT NOT NULL,price REAL NOT NULL,data TEXT NOT NULL,PRIMARY KEY(quote_id,checked_at));
CREATE INDEX history_sku ON observations(sku,checked_at);
CREATE TABLE runs(id TEXT PRIMARY KEY,shop_id TEXT NOT NULL REFERENCES shops(id),trigger TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,finished_at TEXT,error TEXT,list_complete INTEGER NOT NULL DEFAULT 0,seen_count INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_active_shop ON runs(shop_id) WHERE status IN ('queued','running');
CREATE TABLE jobs(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),kind TEXT NOT NULL,page INTEGER NOT NULL DEFAULT 1,source_id TEXT,status TEXT NOT NULL DEFAULT 'queued',lease_until TEXT,error TEXT,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX jobs_run ON jobs(run_id,status);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,expires_at TEXT NOT NULL);
CREATE TABLE login_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE platform_limits(platform TEXT PRIMARY KEY,next_at TEXT NOT NULL);
CREATE TABLE leads(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
CREATE TABLE audit(id TEXT PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL);
